type Pre = (string | number)[];
interface Ver { M: number; m: number; p: number; pre: Pre; }
interface Comp { op: string; v: Ver; }
type CSet = Comp[];

const V = (M: number, m: number, p: number, pre: Pre = []): Ver => ({ M, m, p, pre });

function cmpPre(a: Pre, b: Pre): number {
  if (a.length === 0 && b.length === 0) return 0;
  if (a.length === 0) return 1;
  if (b.length === 0) return -1;
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    const x = a[i], y = b[i];
    if (x === y) continue;
    const xn = typeof x === "number", yn = typeof y === "number";
    if (xn && yn) return (x as number) < (y as number) ? -1 : 1;
    if (xn) return -1;
    if (yn) return 1;
    return (x as string) < (y as string) ? -1 : 1;
  }
  return a.length === b.length ? 0 : a.length < b.length ? -1 : 1;
}

function cmpV(a: Ver, b: Ver): number {
  if (a.M !== b.M) return a.M < b.M ? -1 : 1;
  if (a.m !== b.m) return a.m < b.m ? -1 : 1;
  if (a.p !== b.p) return a.p < b.p ? -1 : 1;
  return cmpPre(a.pre, b.pre);
}

interface Partial { M: number | null; m: number | null; p: number | null; pre: Pre | null; }

const PARTIAL = /^[vV]?(\d+|[xX*])(?:\.(\d+|[xX*])(?:\.(\d+|[xX*])(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+[0-9A-Za-z.-]+)?)?)?$/;

function parsePartial(s: string): Partial | null {
  const r = PARTIAL.exec(s);
  if (!r) return null;
  const num = (x: string | undefined): number | null =>
    x === undefined || /[xX*]/.test(x) ? null : Number(x);
  const M = num(r[1]);
  let m = num(r[2]);
  let p = num(r[3]);
  let pre: Pre | null = null;
  if (m === null) p = null;
  if (p !== null && r[4] !== undefined) {
    pre = r[4].split(".").map((id) => (/^\d+$/.test(id) ? Number(id) : id));
  }
  return { M, m, p, pre };
}

const NONE = (): CSet => [{ op: "<", v: V(0, 0, 0, [0]) }];

function expand(op: string, P: Partial): CSet {
  const { M, m, p, pre } = P;
  const xM = M === null, xm = m === null, xp = p === null;
  if (op === "^") {
    if (xM) return [];
    const Mn = M as number;
    if (xm) return [{ op: ">=", v: V(Mn, 0, 0) }, { op: "<", v: V(Mn + 1, 0, 0, [0]) }];
    const mn = m as number;
    if (xp) {
      if (Mn === 0) return [{ op: ">=", v: V(Mn, mn, 0) }, { op: "<", v: V(Mn, mn + 1, 0, [0]) }];
      return [{ op: ">=", v: V(Mn, mn, 0) }, { op: "<", v: V(Mn + 1, 0, 0, [0]) }];
    }
    const pn = p as number;
    const lo = { op: ">=", v: V(Mn, mn, pn, pre || []) };
    if (Mn === 0) {
      if (mn === 0) return [lo, { op: "<", v: V(Mn, mn, pn + 1, [0]) }];
      return [lo, { op: "<", v: V(Mn, mn + 1, 0, [0]) }];
    }
    return [lo, { op: "<", v: V(Mn + 1, 0, 0, [0]) }];
  }
  if (op === "~" || op === "~>") {
    if (xM) return [];
    const Mn = M as number;
    if (xm) return [{ op: ">=", v: V(Mn, 0, 0) }, { op: "<", v: V(Mn + 1, 0, 0, [0]) }];
    const mn = m as number;
    if (xp) return [{ op: ">=", v: V(Mn, mn, 0) }, { op: "<", v: V(Mn, mn + 1, 0, [0]) }];
    return [
      { op: ">=", v: V(Mn, mn, p as number, pre || []) },
      { op: "<", v: V(Mn, mn + 1, 0, [0]) },
    ];
  }
  let gtlt = op;
  const anyX = xM || xm || xp;
  if (gtlt === "=" && anyX) gtlt = "";
  if (xM) {
    if (gtlt === ">" || gtlt === "<") return NONE();
    return [];
  }
  const Mn = M as number;
  if (gtlt && anyX) {
    let M2 = Mn;
    let mm = xm ? 0 : (m as number);
    let prr: Pre = [];
    if (gtlt === ">") {
      gtlt = ">=";
      if (xm) { M2 = Mn + 1; mm = 0; } else { mm = mm + 1; }
    } else if (gtlt === "<=") {
      gtlt = "<";
      if (xm) { M2 = Mn + 1; mm = 0; } else { mm = mm + 1; }
    }
    if (gtlt === "<") prr = [0];
    return [{ op: gtlt, v: V(M2, mm, 0, prr) }];
  }
  if (xm) return [{ op: ">=", v: V(Mn, 0, 0) }, { op: "<", v: V(Mn + 1, 0, 0, [0]) }];
  const mn = m as number;
  if (xp) return [{ op: ">=", v: V(Mn, mn, 0) }, { op: "<", v: V(Mn, mn + 1, 0, [0]) }];
  return [{ op: gtlt || "=", v: V(Mn, mn, p as number, pre || []) }];
}

function hyphenComps(a: Partial, b: Partial): CSet {
  const out: CSet = [];
  if (a.M !== null) {
    if (a.m === null) out.push({ op: ">=", v: V(a.M, 0, 0) });
    else if (a.p === null) out.push({ op: ">=", v: V(a.M, a.m, 0) });
    else out.push({ op: ">=", v: V(a.M, a.m, a.p, a.pre || []) });
  }
  if (b.M !== null) {
    if (b.m === null) out.push({ op: "<", v: V(b.M + 1, 0, 0, [0]) });
    else if (b.p === null) out.push({ op: "<", v: V(b.M, b.m + 1, 0, [0]) });
    else out.push({ op: "<=", v: V(b.M, b.m, b.p, b.pre || []) });
  }
  return out;
}

function parseSet(s: string): CSet | null {
  s = s.trim();
  const hy = s.split(/\s+-\s+/);
  if (hy.length === 2) {
    const a = parsePartial(hy[0].trim());
    const b = parsePartial(hy[1].trim());
    if (!a || !b) return null;
    return hyphenComps(a, b);
  }
  s = s.replace(/(<=|>=|<|>|=|\^|~>|~)\s+/g, "$1");
  const tokens = s.split(/\s+/).filter((t) => t.length > 0);
  const out: CSet = [];
  for (const t of tokens) {
    const r = /^(\^|~>|~|<=|>=|<|>|=)?(.*)$/.exec(t)!;
    const P = parsePartial(r[2]);
    if (!P) return null;
    for (const c of expand(r[1] || "", P)) out.push(c);
  }
  return out;
}

function parseRange(r: string): CSet[] {
  const sets: CSet[] = [];
  for (const part of r.split("||")) {
    const cs = parseSet(part);
    if (cs) sets.push(cs);
  }
  return sets;
}

function testComp(c: Comp, v: Ver): boolean {
  const k = cmpV(v, c.v);
  switch (c.op) {
    case ">": return k > 0;
    case ">=": return k >= 0;
    case "<": return k < 0;
    case "<=": return k <= 0;
    default: return k === 0;
  }
}

function matchSet(s: CSet, v: Ver): boolean {
  for (const c of s) if (!testComp(c, v)) return false;
  if (v.pre.length > 0) {
    let ok = false;
    for (const c of s) {
      if (c.v.pre.length > 0 && c.v.M === v.M && c.v.m === v.m && c.v.p === v.p) {
        ok = true;
        break;
      }
    }
    if (!ok) return false;
  }
  return true;
}

function matchRange(r: CSet[], v: Ver): boolean {
  for (const s of r) if (matchSet(s, v)) return true;
  return false;
}

export function solve(sub: string, sup: string): boolean {
  const A = parseRange(sub);
  const B = parseRange(sup);
  if (A.length === 0) return true;
  const cands: Ver[] = [V(0, 0, 0), V(0, 0, 0, [0])];
  for (const rng of [A, B]) {
    for (const s of rng) {
      for (const c of s) {
        const b = c.v;
        cands.push(b);
        cands.push(V(b.M, b.m, b.p));
        cands.push(V(b.M, b.m, b.p + 1));
        cands.push(V(b.M, b.m, b.p, [0]));
        cands.push(V(b.M, b.m, b.p + 1, [0]));
        if (b.pre.length > 0) cands.push(V(b.M, b.m, b.p, b.pre.concat([0])));
      }
    }
  }
  for (const v of cands) {
    if (matchRange(A, v) && !matchRange(B, v)) return false;
  }
  return true;
}

