const NUM = "0|[1-9]\\d*";
const XID = `${NUM}|[xX*]`;
const PRID = `(?:${NUM}|\\d*[a-zA-Z-][a-zA-Z0-9-]*)`;
const PRE = `(?:-(${PRID}(?:\\.${PRID})*))`;
const BUILD = `(?:\\+([a-zA-Z0-9-]+(?:\\.[a-zA-Z0-9-]+)*))`;
const GTLT = "((?:<|>)?=?)";
const XPLAIN = `[v=\\s]*(${XID})(?:\\.(${XID})(?:\\.(${XID})(?:${PRE})?(?:${BUILD})?)?)?`;

const HYPHEN = new RegExp(`^\\s*(${XPLAIN})\\s+-\\s+(${XPLAIN})\\s*$`);
const COMPARATOR_TRIM = new RegExp(`(\\s*)${GTLT}\\s*(${XPLAIN})`, "g");
const TILDE_TRIM = /(\s*)(?:~>?)\s+/g;
const CARET_TRIM = /(\s*)(?:\^)\s+/g;
const XRANGE = new RegExp(`^${GTLT}\\s*${XPLAIN}$`);
const TILDE = new RegExp(`^(?:~>?)${XPLAIN}$`);
const CARET = new RegExp(`^(?:\\^)${XPLAIN}$`);
const STAR = /(<|>)?=?\s*\*/;
const GTE0 = /^\s*>=\s*0\.0\.0\s*$/;
const COMPARATOR = new RegExp(
  `^${GTLT}\\s*v?(${NUM})\\.(${NUM})\\.(${NUM})(?:${PRE})?(?:${BUILD})?$`
);

const MAX_SAFE = 9007199254740991;
const NULL_SET = "<0.0.0-0";

function isX(id: string | undefined): boolean {
  return !id || id.toLowerCase() === "x" || id === "*";
}

function hyphenReplace(
  _$0: string,
  from: string,
  fM: string,
  fm: string,
  fp: string,
  fpr: string,
  _fb: string,
  to: string,
  tM: string,
  tm: string,
  tp: string,
  tpr: string
): string {
  if (isX(fM)) from = "";
  else if (isX(fm)) from = `>=${fM}.0.0`;
  else if (isX(fp)) from = `>=${fM}.${fm}.0`;
  else if (fpr) from = `>=${from}`;
  else from = `>=${from}`;

  if (isX(tM)) to = "";
  else if (isX(tm)) to = `<${+tM + 1}.0.0-0`;
  else if (isX(tp)) to = `<${tM}.${+tm + 1}.0-0`;
  else if (tpr) to = `<=${tM}.${tm}.${tp}-${tpr}`;
  else to = `<=${to}`;
  return `${from} ${to}`.trim();
}

function replaceTilde(comp: string): string {
  return comp.replace(TILDE, (_: string, M: string, m: string, p: string, pr: string) => {
    if (isX(M)) return "";
    if (isX(m)) return `>=${M}.0.0 <${+M + 1}.0.0-0`;
    if (isX(p)) return `>=${M}.${m}.0 <${M}.${+m + 1}.0-0`;
    if (pr) return `>=${M}.${m}.${p}-${pr} <${M}.${+m + 1}.0-0`;
    return `>=${M}.${m}.${p} <${M}.${+m + 1}.0-0`;
  });
}

function replaceCaret(comp: string): string {
  return comp.replace(CARET, (_: string, M: string, m: string, p: string, pr: string) => {
    if (isX(M)) return "";
    if (isX(m)) {
      if (M === "0") return `>=${M}.0.0 <${+M + 1}.0.0-0`;
      return `>=${M}.0.0 <${+M + 1}.0.0-0`;
    }
    if (isX(p)) {
      if (M === "0") return `>=${M}.${m}.0 <${M}.${+m + 1}.0-0`;
      return `>=${M}.${m}.0 <${+M + 1}.0.0-0`;
    }
    if (pr) {
      if (M === "0") {
        if (m === "0") return `>=${M}.${m}.${p}-${pr} <${M}.${m}.${+p + 1}-0`;
        return `>=${M}.${m}.${p}-${pr} <${M}.${+m + 1}.0-0`;
      }
      return `>=${M}.${m}.${p}-${pr} <${+M + 1}.0.0-0`;
    }
    if (M === "0") {
      if (m === "0") return `>=${M}.${m}.${p} <${M}.${m}.${+p + 1}-0`;
      return `>=${M}.${m}.${p} <${M}.${+m + 1}.0-0`;
    }
    return `>=${M}.${m}.${p} <${+M + 1}.0.0-0`;
  });
}

function replaceXRange(comp: string): string {
  return comp.replace(
    XRANGE,
    (ret: string, gtlt: string, M: string, m: string, p: string) => {
      const xM = isX(M);
      const xm = xM || isX(m);
      const xp = xm || isX(p);
      const anyX = xp;
      if (gtlt === "=" && anyX) gtlt = "";
      let pr = "";
      if (xM) {
        if (gtlt === ">" || gtlt === "<") ret = NULL_SET;
        else ret = "*";
      } else if (gtlt && anyX) {
        let Mn: string | number = M;
        let mn: string | number = m;
        let pn: string | number = p;
        if (xm) mn = 0;
        pn = 0;
        if (gtlt === ">") {
          gtlt = ">=";
          if (xm) {
            Mn = +M + 1;
            mn = 0;
            pn = 0;
          } else {
            mn = +m + 1;
            pn = 0;
          }
        } else if (gtlt === "<=") {
          gtlt = "<";
          if (xm) Mn = +M + 1;
          else mn = +m + 1;
        }
        if (gtlt === "<") pr = "-0";
        ret = `${gtlt}${Mn}.${mn}.${pn}${pr}`;
      } else if (xm) {
        ret = `>=${M}.0.0 <${+M + 1}.0.0-0`;
      } else if (xp) {
        ret = `>=${M}.${m}.0 <${M}.${+m + 1}.0-0`;
      }
      return ret;
    }
  );
}

function parseComparatorString(comp: string): string {
  const each = (s: string, f: (c: string) => string) =>
    s.trim().split(/\s+/).map(f).join(" ");
  comp = each(comp, replaceCaret);
  comp = each(comp, replaceTilde);
  comp = each(comp, replaceXRange);
  comp = comp.trim().replace(STAR, "");
  return comp;
}

function makeComparator(comp: string): string {
  comp = comp.trim().split(/\s+/).join(" ");
  if (comp === "") return "";
  if (comp.length > 256) throw new TypeError("too long");
  const m = COMPARATOR.exec(comp);
  if (!m) throw new TypeError("Invalid comparator");
  let op = m[1] || "";
  if (op === "=") op = "";
  for (const i of [2, 3, 4]) {
    if (Number(m[i]) > MAX_SAFE) throw new TypeError("Invalid version");
  }
  return `${op}${m[2]}.${m[3]}.${m[4]}${m[5] ? "-" + m[5] : ""}`;
}

function parseRange(range: string): string[] {
  range = range.trim();
  range = range.replace(HYPHEN, hyphenReplace as any);
  range = range.replace(COMPARATOR_TRIM, "$1$2$3");
  range = range.replace(TILDE_TRIM, "$1~");
  range = range.replace(CARET_TRIM, "$1^");
  range = range.split(/\s+/).join(" ");

  const list = range
    .split(" ")
    .map((c) => parseComparatorString(c))
    .join(" ")
    .split(/\s+/)
    .map((c) => c.trim().replace(GTE0, ""));

  const map = new Map<string, string>();
  for (const c of list) {
    const v = makeComparator(c);
    if (v === NULL_SET) return [v];
    map.set(v, v);
  }
  if (map.size > 1 && map.has("")) map.delete("");
  return [...map.values()];
}

function normalize(range: string): string {
  let sets = range
    .split("||")
    .map((r) => parseRange(r.trim()))
    .filter((c) => c.length);
  if (!sets.length) throw new TypeError("Invalid range");

  if (sets.length > 1) {
    const first = sets[0];
    sets = sets.filter((c) => c[0] !== NULL_SET);
    if (sets.length === 0) sets = [first];
    else if (sets.length > 1) {
      for (const c of sets) {
        if (c.length === 1 && c[0] === "") {
          sets = [c];
          break;
        }
      }
    }
  }
  return sets.map((c) => c.join(" ").trim()).join("||") || "*";
}

export function solve(id: string): boolean {
  if (typeof id !== "string") return false;
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const yy = parseInt(m[1], 10);
  let mm = parseInt(m[2], 10);
  const dd = parseInt(m[3], 10);
  const serial = m[4];
  const tenDigit = serial.length === 4;

  let year: number;
  if (tenDigit) {
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  } else {
    if (yy >= 54) return false;
    if (serial === "000") return false;
    year = 1900 + yy;
  }

  // Month offsets: +50 for women, +20 from 2004 (only valid for 2004 and later)
  let plus20 = false;
  if (mm > 50) mm -= 50;
  if (mm > 20) {
    plus20 = true;
    mm -= 20;
  }
  if (mm < 1 || mm > 12) return false;
  if (plus20 && year < 2004) return false;

  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > days[mm - 1]) return false;

  if (tenDigit) {
    const first9 = parseInt(m[1] + m[2] + m[3] + serial.slice(0, 3), 10);
    const r = first9 % 11;
    const expected = r === 10 ? 0 : r;
    if (parseInt(serial[3], 10) !== expected) return false;
  }

  return true;
}

const MAX_LENGTH = 256;
const MAX_SAFE_BUILD_LENGTH = MAX_LENGTH - 6;
const MAX_SAFE_INT = Number.MAX_SAFE_INTEGER;
const LDN = '[a-zA-Z0-9-]';

// Bound the repeating tokens the same way node-semver does, so very long
// inputs are accepted or rejected exactly as npm would.
function makeSafe(v: string): string {
  const reps: [string, number][] = [
    ['\\s', 1],
    ['\\d', MAX_LENGTH],
    [LDN, MAX_SAFE_BUILD_LENGTH],
  ];
  for (const [tok, max] of reps) {
    v = v
      .split(`${tok}*`).join(`${tok}{0,${max}}`)
      .split(`${tok}+`).join(`${tok}{1,${max}}`);
  }
  return v;
}

const NUMID = '0|[1-9]\\d*';
const NUMIDL = '\\d+';
const NONNUM = `\\d*[a-zA-Z-]${LDN}*`;
const MAINV = `(${NUMID})\\.(${NUMID})\\.(${NUMID})`;
const MAINVL = `(${NUMIDL})\\.(${NUMIDL})\\.(${NUMIDL})`;
const PRID = `(?:${NONNUM}|${NUMID})`;
const PRIDL = `(?:${NONNUM}|${NUMIDL})`;
const PRE = `(?:-(${PRID}(?:\\.${PRID})*))`;
const PREL = `(?:-?(${PRIDL}(?:\\.${PRIDL})*))`;
const BUILDID = `${LDN}+`;
const BUILD = `(?:\\+(${BUILDID}(?:\\.${BUILDID})*))`;
const FULLPLAIN = `v?${MAINV}${PRE}?${BUILD}?`;
const LOOSEPLAIN = `[v=\\s]*${MAINVL}${PREL}?${BUILD}?`;
const GTLT = '((?:<|>)?=?)';
const XID = `${NUMID}|x|X|\\*`;
const XPLAIN = `[v=\\s]*(${XID})(?:\\.(${XID})(?:\\.(${XID})(?:${PRE})?${BUILD}?)?)?`;

const R = (s: string, g = false): RegExp => new RegExp(makeSafe(s), g ? 'g' : undefined);

const reFull = R(`^${FULLPLAIN}$`);
const reBuild = R(BUILD);
const reXRange = R(`^${GTLT}\\s*${XPLAIN}$`);
const reTildeTrim = R(`(\\s*)(?:~>?)\\s+`, true);
const reTilde = R(`^(?:~>?)${XPLAIN}$`);
const reCaretTrim = R(`(\\s*)(?:\\^)\\s+`, true);
const reCaret = R(`^(?:\\^)${XPLAIN}$`);
const reComparator = R(`^${GTLT}\\s*(${FULLPLAIN})$|^$`);
const reCompTrim = R(`(\\s*)${GTLT}\\s*(${LOOSEPLAIN}|${XPLAIN})`, true);
const reHyphen = R(`^\\s*(${XPLAIN})\\s+-\\s+(${XPLAIN})\\s*$`);
const reStar = R('(<|>)?=?\\s*\\*');
const reGTE0 = R('^\\s*>=\\s*0\\.0\\.0\\s*$');

const isX = (id: string | undefined): boolean =>
  !id || id.toLowerCase() === 'x' || id === '*';

function semverVersion(v: string): string {
  if (v.length > MAX_LENGTH) throw new Error('too long');
  const m = v.trim().match(reFull);
  if (!m) throw new Error('invalid version');
  const major = +m[1], minor = +m[2], patch = +m[3];
  if (major > MAX_SAFE_INT || major < 0) throw new Error('bad major');
  if (minor > MAX_SAFE_INT || minor < 0) throw new Error('bad minor');
  if (patch > MAX_SAFE_INT || patch < 0) throw new Error('bad patch');
  const pre: string[] = m[4]
    ? m[4].split('.').map((id) => {
        if (/^[0-9]+$/.test(id)) {
          const num = +id;
          if (num >= 0 && num < MAX_SAFE_INT) return String(num);
        }
        return id;
      })
    : [];
  return `${major}.${minor}.${patch}` + (pre.length ? `-${pre.join('.')}` : '');
}

function compValue(comp: string): string {
  comp = comp.trim().split(/\s+/).join(' ');
  const m = comp.match(reComparator);
  if (!m) throw new Error('invalid comparator');
  let op = m[1] !== undefined ? m[1] : '';
  if (op === '=') op = '';
  if (!m[2]) return '';
  return op + semverVersion(m[2]);
}

