  if (isX(fM)) from = '';
  else if (isX(fm)) from = `>=${fM}.0.0`;
  else if (isX(fp)) from = `>=${fM}.${fm}.0`;
  else if (fpr) from = `>=${from}`;
  else from = `>=${from}`;

  if (isX(tM)) to = '';
  else if (isX(tm)) to = `<${+(tM as string) + 1}.0.0-0`;
  else if (isX(tp)) to = `<${tM}.${+(tm as string) + 1}.0-0`;
  else if (tpr) to = `<=${tM}.${tm}.${tp}-${tpr}`;
  else to = `<=${to}`;

  return `${from} ${to}`.trim();
}

function replaceCaret(comp: string): string {
  return comp.replace(reCaret, (_: string, M: string, m?: string, p?: string, pr?: string) => {
    if (isX(M)) return '';
    if (isX(m)) return `>=${M}.0.0 <${+M + 1}.0.0-0`;
    if (isX(p)) {
      if (M === '0') return `>=${M}.${m}.0 <${M}.${+(m as string) + 1}.0-0`;
      return `>=${M}.${m}.0 <${+M + 1}.0.0-0`;
    }
    if (pr) {
      if (M === '0') {
        if (m === '0') return `>=${M}.${m}.${p}-${pr} <${M}.${m}.${+(p as string) + 1}-0`;
        return `>=${M}.${m}.${p}-${pr} <${M}.${+(m as string) + 1}.0-0`;
      }
      return `>=${M}.${m}.${p}-${pr} <${+M + 1}.0.0-0`;
    }
    if (M === '0') {
      if (m === '0') return `>=${M}.${m}.${p} <${M}.${m}.${+(p as string) + 1}-0`;
      return `>=${M}.${m}.${p} <${M}.${+(m as string) + 1}.0-0`;
    }
    return `>=${M}.${m}.${p} <${+M + 1}.0.0-0`;
  });
}

function replaceTilde(comp: string): string {
  return comp.replace(reTilde, (_: string, M: string, m?: string, p?: string, pr?: string) => {
    if (isX(M)) return '';
    if (isX(m)) return `>=${M}.0.0 <${+M + 1}.0.0-0`;
    if (isX(p)) return `>=${M}.${m}.0 <${M}.${+(m as string) + 1}.0-0`;
    if (pr) return `>=${M}.${m}.${p}-${pr} <${M}.${+(m as string) + 1}.0-0`;
    return `>=${M}.${m}.${p} <${M}.${+(m as string) + 1}.0-0`;
  });
}

function replaceXRange(comp: string): string {
  comp = comp.trim();
  return comp.replace(
    reXRange,
    (ret: string, gtlt: string, M: string, m0?: string, p0?: string) => {
      let m: string | number | undefined = m0;
      let p: string | number | undefined = p0;
      let Mv: string | number = M;
      const xM = isX(M);
      const xm = xM || isX(m0);
      const xp = xm || isX(p0);
      const anyX = xp;
      if (gtlt === '=' && anyX) gtlt = '';
      let pr = '';
      if (xM) {
        if (gtlt === '>' || gtlt === '<') ret = '<0.0.0-0';
        else ret = '*';
      } else if (gtlt && anyX) {
        if (xm) m = 0;
        p = 0;
        if (gtlt === '>') {
          gtlt = '>=';
          if (xm) {
            Mv = +Mv + 1;
            m = 0;
            p = 0;
          } else {
            m = +(m as string) + 1;
            p = 0;
          }
        } else if (gtlt === '<=') {
          gtlt = '<';
          if (xm) Mv = +Mv + 1;
          else m = +(m as string) + 1;
        }
        if (gtlt === '<') pr = '-0';
        ret = `${gtlt + Mv}.${m}.${p}${pr}`;
      } else if (xm) {
        ret = `>=${Mv}.0.0 <${+Mv + 1}.0.0-0`;
      } else if (xp) {
        ret = `>=${Mv}.${m}.0 <${Mv}.${+(m as string) + 1}.0-0`;
      }
      return ret;
    }
  );
}

function parseComparator(comp: string): string {
  comp = comp.replace(reBuild, '');
  comp = comp.trim().split(/\s+/).map(replaceCaret).join(' ');
  comp = comp.trim().split(/\s+/).map(replaceTilde).join(' ');
  comp = comp.split(/\s+/).map(replaceXRange).join(' ');
  comp = comp.trim().replace(reStar, '');
  return comp;
}

function parseRange(range: string): string[] {
  range = range.replace(reHyphen, hyphenReplace as any);
  range = range.replace(reCompTrim, '$1$2$3');
  range = range.replace(reTildeTrim, '$1~');
  range = range.replace(reCaretTrim, '$1^');
  const list = range
    .split(' ')
    .map(parseComparator)
    .join(' ')
    .split(/\s+/)
    .map((c) => c.trim().replace(reGTE0, ''));
  const values = list.map(compValue);
  const map = new Map<string, string>();
  for (const v of values) {
    if (v === '<0.0.0-0') return [v];
    map.set(v, v);
  }
  if (map.size > 1 && map.has('')) map.delete('');
  return [...map.values()];
}

export function solve(range: string): string | null {
  try {
    const raw = range.trim().replace(/\s+/g, ' ');
    let set = raw
      .split('||')
      .map((r) => parseRange(r.trim()))
      .filter((c) => c.length);
    if (!set.length) return null;
    if (set.length > 1) {
      const first = set[0];
      set = set.filter((c) => c[0] !== '<0.0.0-0');
      if (set.length === 0) {
        set = [first];
      } else if (set.length > 1) {
        for (const c of set) {
          if (c.length === 1 && c[0] === '') {
            set = [c];
            break;
          }
        }
      }
    }
    const out = set.map((c) => c.map((x) => x.trim()).join(' ')).join('||');
    return out === '' ? '*' : out;
  } catch {
    return null;
  }
}

export function solve(id: string): boolean {
  if (typeof id !== "string") return false;
  const m = /^(\d{6})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const datePart = m[1];
  const serialPart = m[2];

  const yy = parseInt(datePart.slice(0, 2), 10);
  let mm = parseInt(datePart.slice(2, 4), 10);
  const dd = parseInt(datePart.slice(4, 6), 10);

  let year: number;

  if (serialPart.length === 3) {
    // 9-digit form: issued before 1954
    if (yy >= 54) return false;
    if (serialPart === "000") return false;
    year = 1900 + yy;
  } else {
    // 10-digit form
    year = yy < 54 ? 2000 + yy : 1900 + yy;
    const first9 = parseInt(datePart + serialPart.slice(0, 3), 10);
    const checkDigit = parseInt(serialPart[3], 10);
    let mod = first9 % 11;
    if (mod === 10) mod = 0;
    if (mod !== checkDigit) return false;
  }

  // Month offsets
  let month: number;
  if (mm >= 1 && mm <= 12) {
    month = mm;
  } else if (mm >= 51 && mm <= 62) {
    month = mm - 50;
  } else if (mm >= 21 && mm <= 32 && year >= 2004) {
    month = mm - 20;
  } else if (mm >= 71 && mm <= 82 && year >= 2004) {
    month = mm - 70;
  } else {
    return false;
  }

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) return false;

  return true;
}
